-- 242 historical sales, Oct 2023 – Oct 13, 2026. Runs as one transaction: all or nothing.
-- Markup and consignor payout are calculated by the database's own tier rules as each item is saved.

begin;

do $$
begin
  if exists (select 1 from public.consignment_items) or exists (select 1 from public.historical_sales) then
    raise exception 'Items or historical sales already exist. Run 02_wipe.sql first (this import is meant for an empty system).';
  end if;
end $$;

