-- 4. Sales. Credited round-robin to your active Sales Associate accounts (none = left blank);
--    payments marked verified by your first active Manager or Owner account.
create temporary table _assoc on commit drop as
  select (row_number() over (order by created_at, id) - 1)::int as n, id
  from public.profiles where role = 'sales_associate' and is_active;
create temporary table _verifier on commit drop as
  select id from public.profiles where role in ('manager', 'super_admin') and is_active
  order by case role when 'manager' then 0 else 1 end, created_at limit 1;

insert into public.sales_transactions
  (id, item_id, buyer_name, buyer_phone, sales_associate_id, sale_type, layaway_months, payment_status,
   payment_verified_by, payment_verified_at, payout_status, payout_due_by, payout_released_at, sold_at)
select v.id::uuid, v.item_id::uuid, v.buyer_name, v.buyer_phone,
       (select a.id from _assoc a where a.n = v.k % nullif((select count(*) from _assoc), 0)),
       v.sale_type, v.layaway_months::int, v.payment_status,
       case when v.payment_status = 'verified' then (select id from _verifier) end,
       v.payment_verified_at::timestamptz, v.payout_status, v.payout_due_by::date, v.payout_released_at::timestamptz,
