-- Fully paid past layaways: the sale step reserved them; completing payment marks them Sold (same as the app)
update public.listings l set inventory_status = 'sold'
from public.sales_transactions s
where s.item_id = l.item_id and s.sale_type = 'layaway' and s.payment_status = 'verified' and l.inventory_status = 'reserved';

