-- 7. Back-date the activity trail, timestamps and payouts so everything reads as real history
delete from public.notifications where item_id in (select id from public.consignment_items);  -- no emails for mock data
delete from public.stage_history where item_id in (select id from public.consignment_items);

-- Listed items: inquiry -> received -> authentication -> photography -> pricing -> published, spread from intake to listing
insert into public.stage_history (item_id, from_stage, to_stage, changed_at)
select c.id, t.from_stage::public.pipeline_stage, t.to_stage::public.pipeline_stage,
       c.created_at + (l.published_at - c.created_at) * t.f
from public.consignment_items c
join public.listings l on l.item_id = c.id
cross join (values (null, 'customer_inquiry', 0.0), ('customer_inquiry', 'arrivals_receiving', 0.25),
                   ('arrivals_receiving', 'authentication_service', 0.4), ('authentication_service', 'photography', 0.65),
                   ('photography', 'pricing_markup', 0.85), ('pricing_markup', 'publish_item', 1.0)) as t(from_stage, to_stage, f);

-- ...then Sold on the sale date
insert into public.stage_history (item_id, from_stage, to_stage, changed_at)
select c.id, 'publish_item', 'sold', s.sold_at
from public.consignment_items c join public.sales_transactions s on s.item_id = c.id
where c.current_stage = 'sold';

