-- updated_at is normally stamped with "now" by a trigger; switch those two triggers off just for this fix-up
alter table public.consignment_items disable trigger set_consignment_items_updated_at;
alter table public.listings disable trigger set_listings_updated_at;

update public.consignment_items c set updated_at = s.sold_at
from public.sales_transactions s where s.item_id = c.id and c.current_stage = 'sold';
update public.consignment_items c set updated_at = l.published_at
from public.listings l where l.item_id = c.id and c.current_stage = 'publish_item';
update public.consignment_items c set updated_at = v.ts::timestamptz
from (values
  ('3151e0f4-0836-572d-91b3-bb58e1fbfb3b', '2023-11-16T10:17:00+08:00'),
