update public.listings l
set updated_at = coalesce(s.sold_at, l.published_at)
from public.sales_transactions s
where s.item_id = l.item_id;
update public.listings set updated_at = published_at where inventory_status = 'published';

alter table public.consignment_items enable trigger set_consignment_items_updated_at;
alter table public.listings enable trigger set_listings_updated_at;

commit;

-- Quick check (compare with the README counts in the workbook)
select
  (select count(*) from public.consignors) as consignors,
  (select count(*) from public.consignment_items) as items,
  (select count(*) from public.consignment_items where current_stage = 'sold') as sold,
  (select count(*) from public.listings where inventory_status = 'published') as available,
  (select count(*) from public.listings where inventory_status = 'reserved') as reserved,
  (select count(*) from public.consignment_items where current_stage in ('closed_fake','closed_rejected')) as closed,
  (select count(*) from public.historical_sales) as historical_sales,
  (select to_char(sum(revenue), 'FM999,999,999') from public.monthly_brand_sales) as total_revenue;